// Presse locale : chaque club est suivi par les rédactions de son pays (championnat
// britannique départagé par la fédération du club : Ulster en Irlande, Glasgow et
// Édimbourg en Écosse, les quatre provinces galloises au pays de Galles).
const PRESS_REGIONS=Object.freeze({eu:'Coupes d’Europe',fr:'France',en:'Angleterre',ie:'Irlande',sco:'Écosse',wal:'Pays de Galles',it:'Italie',za:'Afrique du Sud',ge:'Géorgie',nz:'Nouvelle-Zélande',au:'Australie',pac:'Îles du Pacifique',jp:'Japon'});
const COUNTRY_REGIONS=Object.freeze({FR:'fr',IE:'ie',IT:'it',ZA:'za',GE:'ge',NZ:'nz',AU:'au',FJ:'pac',WS:'pac',TO:'pac',JP:'jp'});
const GB_UNIONS=Object.freeze({ulster:'ie',glasgow:'sco',edinburgh:'sco',cardiff:'wal',dragons:'wal',ospreys:'wal',scarlets:'wal'});
// Vivier de base d'un pays : ses journalistes sans championnat attitré. S'y ajoutent ceux qui
// suivent le championnat du club (Nationale) et la presse des coupes d'Europe pour les
// championnats qui y qualifient leurs clubs : une clé de presse vaut « pays:championnat ».
const BY_REGION=Object.freeze(Object.fromEntries(Object.keys(PRESS_REGIONS).map(r=>[r,Object.freeze(JOURNALISTS.filter(j=>j.region===r&&!j.leagues))])));
const LEAGUE_PRESS=JOURNALISTS.filter(j=>j.leagues),BY_KEY=new Map();
function regionOf(club){if(!club||typeof club!=='object')return 'fr';if(club.country==='GB'){const key=String(club.key||club.slug||'');return GB_UNIONS[key.slice(key.search(/[:-]/)+1)]||'en';}return COUNTRY_REGIONS[club.country]||'fr';}
function pressKeyOf(club){const region=regionOf(club);return club&&typeof club.leagueId==='string'?region+':'+club.leagueId:region;}
function regionFor(s,clubId=s?.club){if(!s||typeof CDWorldCareer==='undefined'||typeof CDWorldCareer.active!=='function'||!CDWorldCareer.active(s))return 'fr';const clubs=CDWorldCareer.edition(s)?.registry?.clubs;if(!Array.isArray(clubs))return 'fr';return pressKeyOf(clubs[clubId]?.id===clubId?clubs[clubId]:clubs.find(c=>c.id===clubId));}
function journalistsFor(key){key=String(key);if(BY_KEY.has(key))return BY_KEY.get(key);const [region,league]=key.split(':'),base=Object.hasOwn(BY_REGION,region)&&region!=='eu'&&BY_REGION[region].length?BY_REGION[region]:BY_REGION.fr;
 const list=league?Object.freeze([...base,...LEAGUE_PRESS.filter(j=>j.leagues.includes(league)&&(j.region===region||j.region==='eu'))]):base;BY_KEY.set(key,list);return list;}
const norm=(x)=>String(x).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function format(t,subject){return t.replace(/\{s\}/g,'« '+subject+' »');}
